import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.CcKC9xfe.js";const m=JSON.parse('{"title":"DNS records for a mail domain: MX, SPF, DKIM, DMARC and PTR","description":"The DNS records a mail domain needs - A/AAAA, MX, SPF, DKIM, DMARC and PTR - with examples, why nameserver redundancy matters, and how to verify with dig.","frontmatter":{"description":"The DNS records a mail domain needs - A/AAAA, MX, SPF, DKIM, DMARC and PTR - with examples, why nameserver redundancy matters, and how to verify with dig.","head":[["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/installation/dns.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/latest/installation/dns.html"}],["meta",{"property":"og:title","content":"DNS records for a mail domain: MX, SPF, DKIM, DMARC and PTR"}],["meta",{"name":"twitter:title","content":"DNS records for a mail domain: MX, SPF, DKIM, DMARC and PTR"}],["meta",{"property":"og:description","content":"The DNS records a mail domain needs - A/AAAA, MX, SPF, DKIM, DMARC and PTR - with examples, why nameserver redundancy matters, and how to verify with dig."}],["meta",{"name":"twitter:description","content":"The DNS records a mail domain needs - A/AAAA, MX, SPF, DKIM, DMARC and PTR - with examples, why nameserver redundancy matters, and how to verify with dig."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/latest/installation/dns.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/latest/installation/dns.html\\",\\"headline\\":\\"DNS records for a mail domain: MX, SPF, DKIM, DMARC and PTR\\",\\"description\\":\\"The DNS records a mail domain needs - A/AAAA, MX, SPF, DKIM, DMARC and PTR - with examples, why nameserver redundancy matters, and how to verify with dig.\\",\\"dateModified\\":\\"2026-10-31T12:43:41.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/latest/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"DNS records for a mail domain: MX, SPF, DKIM, DMARC and PTR\\",\\"item\\":\\"https://doc.yarilomail.org/latest/installation/dns.html\\"}]}]}"]]},"headers":[],"relativePath":"installation/dns.md","filePath":"installation/dns.md","lastUpdated":1793450621000}'),n={name:"installation/dns.md"};function r(o,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="dns-records-for-a-mail-domain-mx-spf-dkim-dmarc-and-ptr" tabindex="-1">DNS records for a mail domain: MX, SPF, DKIM, DMARC and PTR <a class="header-anchor" href="#dns-records-for-a-mail-domain-mx-spf-dkim-dmarc-and-ptr" aria-label="Permalink to &quot;DNS records for a mail domain: MX, SPF, DKIM, DMARC and PTR&quot;">​</a></h1><p>The DNS records a mail domain needs before yarilo can receive and send mail reliably, and why the nameservers serving them need redundancy of their own. For the cluster-side setup see the <a href="/latest/installation/">Installation Guide</a>.</p><h2 id="why-dns-matters-for-mail" tabindex="-1">Why DNS matters for mail <a class="header-anchor" href="#why-dns-matters-for-mail" aria-label="Permalink to &quot;Why DNS matters for mail&quot;">​</a></h2><p>Every hop of a message starts with a DNS lookup. A sending server resolves the recipient domain&#39;s MX record, then the A/AAAA record of the host it names. Receiving servers look up SPF, DKIM and DMARC to decide whether to accept the message, and check the PTR record of the connecting IP.</p><p>If any of those lookups fails, the message is not lost immediately - sending servers queue and retry for hours or days - but delivery stalls, bounces appear, and reputation suffers. A mail domain is only as reachable as its DNS.</p><h2 id="required-records" tabindex="-1">Required records <a class="header-anchor" href="#required-records" aria-label="Permalink to &quot;Required records&quot;">​</a></h2><p>The minimum set for a production domain served by yarilo behind an inbound MTA. Replace <code>example.<wbr>com</code> and <code>mail.<wbr>example.<wbr>com</code> with your own names.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Record</th><th style="text-align:left;">Name</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;">A / AAAA</td><td style="text-align:left;"><code>mail.<wbr>example.<wbr>com</code></td><td style="text-align:left;">Address of the public mail host (the LoadBalancer IP)</td></tr><tr><td style="text-align:left;">MX</td><td style="text-align:left;"><code>example.<wbr>com</code></td><td style="text-align:left;">Names the host that accepts inbound mail on port 25</td></tr><tr><td style="text-align:left;">TXT (SPF)</td><td style="text-align:left;"><code>example.<wbr>com</code></td><td style="text-align:left;">Which hosts may send mail for the domain</td></tr><tr><td style="text-align:left;">TXT (DKIM)</td><td style="text-align:left;"><code>&lt;selector&gt;.<wbr>_<wbr>domainkey.<wbr>example.<wbr>com</code></td><td style="text-align:left;">Public key used to verify message signatures</td></tr><tr><td style="text-align:left;">TXT (DMARC)</td><td style="text-align:left;"><code>_<wbr>dmarc.<wbr>example.<wbr>com</code></td><td style="text-align:left;">Policy for messages that fail SPF or DKIM</td></tr><tr><td style="text-align:left;">PTR</td><td style="text-align:left;">reverse of the mail host IP</td><td style="text-align:left;">Maps the sending IP back to <code>mail.<wbr>example.<wbr>com</code></td></tr></tbody></table><h3 id="address-record" tabindex="-1">Address record <a class="header-anchor" href="#address-record" aria-label="Permalink to &quot;Address record&quot;">​</a></h3><p>Point the public hostname at the LoadBalancer IP your cluster assigned:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mail.example.com.   3600  IN  A     203.0.113.10</span></span>
<span class="line"><span>mail.example.com.   3600  IN  AAAA  2001:db8::10</span></span></code></pre></div><p>This is the hostname clients connect to for IMAP, POP3 and submission, and the hostname the TLS certificate is issued for.</p><h3 id="mx-record" tabindex="-1">MX record <a class="header-anchor" href="#mx-record" aria-label="Permalink to &quot;MX record&quot;">​</a></h3><p>Name the host that accepts inbound mail for the domain:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>example.com.   3600  IN  MX  10 mail.example.com.</span></span></code></pre></div><p>The MX target must be a hostname with an A/AAAA record, never an IP address and never a CNAME. In a yarilo deployment this host runs the inbound MTA, which delivers over LMTP to <code>yarilo-lmtp-login</code>; that proxy looks up each recipient&#39;s backend and hands the message on - see <a href="/latest/protocols/lmtp.html">LMTP</a>.</p><h3 id="spf" tabindex="-1">SPF <a class="header-anchor" href="#spf" aria-label="Permalink to &quot;SPF&quot;">​</a></h3><p>Declare which hosts may send mail for the domain:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>example.com.   3600  IN  TXT  &quot;v=spf1 mx -all&quot;</span></span></code></pre></div><p><code>mx</code> authorises the MX hosts; add <code>ip4:</code> / <code>ip6:</code> entries for any relay that sends on the domain&#39;s behalf. Use <code>-all</code> (fail) once every sender is listed.</p><h3 id="dkim" tabindex="-1">DKIM <a class="header-anchor" href="#dkim" aria-label="Permalink to &quot;DKIM&quot;">​</a></h3><p>Publish the public key of the signing MTA under a selector:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mail._domainkey.example.com.   3600  IN  TXT  &quot;v=DKIM1; k=rsa; p=MIIBIjANBg...&quot;</span></span></code></pre></div><p>The selector (<code>mail</code> here) is chosen in the MTA&#39;s DKIM configuration. Rotate keys by publishing a new selector before switching the signer to it.</p><h3 id="dmarc" tabindex="-1">DMARC <a class="header-anchor" href="#dmarc" aria-label="Permalink to &quot;DMARC&quot;">​</a></h3><p>Tell receivers what to do with messages that fail SPF and DKIM alignment:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>_dmarc.example.com.   3600  IN  TXT  &quot;v=DMARC1; p=quarantine; rua=mailto:dmarc@example.com&quot;</span></span></code></pre></div><p>Start with <code>p=none</code> to collect reports, then move to <code>quarantine</code> and <code>reject</code> once the reports show only legitimate senders.</p><h3 id="ptr" tabindex="-1">PTR <a class="header-anchor" href="#ptr" aria-label="Permalink to &quot;PTR&quot;">​</a></h3><p>The reverse record is set by whoever controls the IP range - your hosting provider or cloud console, not your domain&#39;s zone:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10.113.0.203.in-addr.arpa.   3600  IN  PTR  mail.example.com.</span></span></code></pre></div><p>The PTR must resolve back to the same hostname the MTA announces in its <code>EHLO</code>. Many receivers reject or greylist connections from IPs without a matching PTR.</p><h2 id="optional-records" tabindex="-1">Optional records <a class="header-anchor" href="#optional-records" aria-label="Permalink to &quot;Optional records&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Record</th><th style="text-align:left;">Name</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;">SRV</td><td style="text-align:left;"><code>_<wbr>imaps.<wbr>_<wbr>tcp</code>, <code>_<wbr>submissions.<wbr>_<wbr>tcp</code>, <code>_<wbr>submission.<wbr>_<wbr>tcp</code></td><td style="text-align:left;">Client autodiscovery (RFC 6186)</td></tr><tr><td style="text-align:left;">SRV</td><td style="text-align:left;"><code>_<wbr>autodiscover.<wbr>_<wbr>tcp</code></td><td style="text-align:left;">Outlook autodiscovery</td></tr><tr><td style="text-align:left;">TXT</td><td style="text-align:left;"><code>_<wbr>mta-sts.<wbr>example.<wbr>com</code></td><td style="text-align:left;">MTA-STS policy for enforced inbound TLS</td></tr><tr><td style="text-align:left;">TXT</td><td style="text-align:left;"><code>_<wbr>smtp.<wbr>_<wbr>tls.<wbr>example.<wbr>com</code></td><td style="text-align:left;">TLS-RPT reporting address</td></tr><tr><td style="text-align:left;">TLSA</td><td style="text-align:left;"><code>_<wbr>25.<wbr>_<wbr>tcp.<wbr>mail.<wbr>example.<wbr>com</code></td><td style="text-align:left;">DANE, only with a DNSSEC-signed zone</td></tr></tbody></table><p>MTA-STS needs more than the TXT record: the policy itself is a text file served over HTTPS at <code>https:/<wbr>/<wbr>mta-sts.<wbr>example.<wbr>com/<wbr>.<wbr>well-known/<wbr>mta-sts.<wbr>txt</code>, so the record alone has no effect until that host is up.</p><p>Autodiscovery lets mail clients find the IMAP and submission hosts from the address alone. Publish implicit TLS with the lower priority value, so clients prefer it over STARTTLS:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>_imaps._tcp.example.com.         3600  IN  SRV  0 1 993  mail.example.com.</span></span>
<span class="line"><span>_submissions._tcp.example.com.   3600  IN  SRV  0 1 465  mail.example.com.</span></span>
<span class="line"><span>_submission._tcp.example.com.    3600  IN  SRV  10 1 587 mail.example.com.</span></span></code></pre></div><p>Thunderbird and Outlook need more than these records. See <a href="/latest/installation/autoconfig.html">Mail client autoconfiguration</a> for the service that answers them and the <code>_<wbr>autodiscover.<wbr>_<wbr>tcp</code> record.</p><h2 id="nameserver-redundancy" tabindex="-1">Nameserver redundancy <a class="header-anchor" href="#nameserver-redundancy" aria-label="Permalink to &quot;Nameserver redundancy&quot;">​</a></h2><p>The records above live on authoritative nameservers, and those are a single point of failure that is easy to overlook. If the only nameserver for <code>example.<wbr>com</code> is down - host maintenance, a provider outage, a DDoS on the DNS host - every lookup above fails at once. Inbound mail queues at the sender, outbound mail is rejected for a missing SPF or PTR match, and clients cannot even resolve <code>mail.<wbr>example.<wbr>com</code> to log in. The mail server itself may be perfectly healthy.</p><p>RFC 2182 recommends at least two authoritative nameservers on separate networks, and most registries refuse to delegate a domain to fewer than two. Running one nameserver and listing it twice under different names does not count: both names fail together.</p><p>A secondary nameserver keeps a live copy of the zone through AXFR zone transfers and keeps answering while the primary is unavailable. It can be a second server you operate in a different network, or a hosted secondary DNS service that pulls the zone from your primary - see <a href="https://seconddns.com/docs/guides/dns-redundancy" target="_blank" rel="noreferrer">DNS redundancy and secondary nameservers</a> for how zone transfers and SOA refresh timers keep the copies in sync.</p><div class="tip custom-block"><p class="custom-block-title">Checking the delegation</p><p>List the nameservers the registry has on file and confirm each answers for the zone:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @ns1.example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SOA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @ns2.example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SOA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span></span></code></pre></div><p>Both SOA answers must return the same serial. A lagging serial means zone transfers are not reaching the secondary - see <a href="https://seconddns.com/docs/guides/axfr-zone-transfer" target="_blank" rel="noreferrer">Understanding AXFR zone transfers</a> for how a transfer is requested and where it typically fails.</p></div><h2 id="verifying-the-records" tabindex="-1">Verifying the records <a class="header-anchor" href="#verifying-the-records" aria-label="Permalink to &quot;Verifying the records&quot;">​</a></h2><p>Check each record from outside your network before sending the first message:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TXT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TXT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail._domainkey.example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TXT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> _dmarc.example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 203.0.113.10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span></span></code></pre></div><p>This sequence:</p><ul><li>confirms the MX points at a resolvable host</li><li>shows the SPF and DMARC policies as receivers see them</li><li>proves the DKIM key is published under the selector the signer uses</li><li>verifies the PTR resolves back to the mail hostname</li></ul><p>::: note DNS changes propagate at the speed of the record&#39;s TTL. Lower the TTL to a few minutes before a planned change, then raise it again once the change has settled. :::</p>`,49)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
